import{_ as o,o as r,c as n,a5 as s}from"./chunks/framework.Bt0SrEfo.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"agent/HoldLog.md","filePath":"agent/HoldLog.md","lastUpdated":1788748072000}'),g={name:"agent/HoldLog.md"};function e(a,t,l,i,d,p){return r(),n("div",null,[...t[0]||(t[0]=[s("<p>先帮我创建需求文档 需求文档：AlphaPath 基金跟踪与决策辅助系统1. 项目背景与目标本项目旨在打造一个轻量级的基金投资辅助工具，通过跟踪基金经理的历史持仓及收益，实现数据化的“跟随决策”。核心目标是实现自动化监控，当目标基金的收益回撤至设定的预警区间时，及时通知用户。2. 核心用户场景<strong>配置层</strong>：用户输入或管理关注的基金经理及买入成本（基金代码、买入日期、买入净值）。<strong>监控层</strong>：系统每日自动抓取目标基金的最新复权净值，与成本进行对比。<strong>决策层</strong>：系统根据 (最新净值 - 买入净值) / 买入净值 &lt;= 5% 的逻辑，筛选出“推荐买入”的标的。3. 功能模块详情3.1 资产管理模块 (Portfolio Management)<strong>基金档案</strong>：存储基金基本信息及监控状态。<strong>成本录入</strong>：支持手动录入或批量导入大佬的买入时间点、成本净值。<strong>类型处理</strong>：支持将不同来源（如 CSV/API）的输入数据标准化为系统格式（包括将字符串类型转换为数值数组以供计算）。3.2 数据获取模块 (Data Acquisition)<strong>接口整合</strong>：接入金融数据服务商 API（如 Tushare），获取基金每日的<strong>复权单位净值</strong>。<strong>数据清洗</strong>：剔除异常数据，确保计算使用的净值已进行分红处理，避免计算误差。<strong>定时调度</strong>：每日收盘后（建议 20:00 后）自动更新所有已关注基金的数据。3.3 监控与预警模块 (Monitoring &amp; Alerting)<strong>收益计算引擎</strong>：实时计算当前持仓的相对收益率。<strong>预警推送</strong>：<strong>监控阈值</strong>：触发条件设定为相对收益 $\\le 5%$。<strong>预警通知</strong>：通过 UI 高亮显示，或通过邮件/即时通讯工具发送通知。4. 技术栈需求<strong>开发环境</strong>：Next.js + TypeScript<strong>组件库</strong>：Ant Design (antd)<em>组件应用</em>：使用 Table 展示持仓，使用 Modal 封装统一的确认与配置交互，使用 Form 处理数据输入。<strong>样式方案</strong>：CSS 模块化，使用伪元素实现圆角渐变边框，UI 风格追求专业、冷峻、高效率。<strong>后端服务</strong>：Next.js API Routes (Serverless Functions) 负责数据抓取和计算。5. 数据逻辑流 (Logic Flow)<strong>输入端</strong>：User -&gt; Input (Code, BuyNav) -&gt; DB Store<strong>调度端</strong>：Cron Job -&gt; API Call -&gt; Fetch Nav -&gt; Update DB<strong>判定端</strong>：If (CurrentNav - BuyNav) / BuyNav &lt;= 0.05 -&gt; Flag as &quot;Buy Signal&quot;<strong>展示端</strong>：UI Dashboard -&gt; Fetch &quot;Buy Signal&quot; -&gt; Render List6. 非功能性需求<strong>数据精度</strong>：必须使用<strong>复权单位净值</strong>，禁止直接使用单位净值计算收益。<strong>性能要求</strong>：前端 Dashboard 需支持秒级响应，数据抓取应在后台异步完成，不阻塞主线程。<strong>类型安全</strong>：严格使用 TypeScript 定义数据接口，确保计算字段的类型一致性。开发优先级建议<strong>P0 (基础)</strong>：建立数据库 Schema 和基本的 API 接口，跑通获取单只基金净值的全流程。<strong>P1 (计算)</strong>：实现收益计算逻辑，并集成到前端 Table 中。<strong>P2 (交互)</strong>：封装 ConfirmWrapper 或 AlertModal 等组件，用于处理买入确认和参数配置。<strong>P3 (推送)</strong>：完成定时任务调度（Cron Job）与预警推送。</p>",1)])])}const u=o(g,[["render",e]]);export{_ as __pageData,u as default};
